This is the classical greedy merge, NOT a transcription of the paper's algorithm. It is included to show that differential testing can only make an implementation's correctness empirical: greedy's factor-2 guarantee is not established, yet it passes these instances.

```python
def _overlap(a, b):
    for k in range(min(len(a), len(b)) - 1, 0, -1):
        if a.endswith(b[:k]):
            return k
    return 0

def _reduce(strings):
    kept = []
    for s in sorted(set(strings), key=lambda x: (-len(x), x)):
        if not any(s in t for t in kept):
            kept.append(s)
    return kept

def superstring(instance):
    strings = _reduce(instance["strings"])
    while len(strings) > 1:
        k, i, j = max((_overlap(a, b), i, j) for i, a in enumerate(strings) for j, b in enumerate(strings) if i != j)
        merged = strings[i] + strings[j][k:]
        strings = _reduce([s for t, s in enumerate(strings) if t not in (i, j)] + [merged])
    return strings[0] if strings else ""
```
